set linesize 32767

DECLARE
    --====================================================================================================
    --type宣言
    --====================================================================================================
    TYPE tVArray    IS VARRAY(10000) OF VARCHAR2(10000);
    TYPE tVArrayINT IS TABLE OF VARCHAR2(100)    INDEX BY BYNARY_INDEGER;
    TYPE tVArraySTR IS TABLE OF VARCHAR2(100000) INDEX BY VARCHAR2(10000);
    
    --====================================================================================================
    --各種変数宣言
    --====================================================================================================
    ------------------------------------------------------------------------------------------------------
    -- 苗字
    ------------------------------------------------------------------------------------------------------
