    ------------------------------------------------------------------------------------------------------
    -- その他変数宣言
    ------------------------------------------------------------------------------------------------------
    v_HumanData   tArraySTR;
    v_AddressData tArraySTR;
    RECORD_CNT NUMBER;

    --====================================================================================================
    --関数宣言
    --====================================================================================================
    -- ==================================================
    -- 指定範囲内でランダムな数値を取得する。
    -- P_FROM 範囲数値（FROM）
    -- P_TO   範囲数値（TO）
    -- ==================================================
    FUNCTION RANDOM_NUMBER(P_FROM IN NUMBER, P_TO IN NUMBER) RETURN NUMBER
    IS
    BEGIN
        RETURN TRUNC(DBMS_RANDOM.VALUE(P_FROM,P_TO + 1), 0);
    END RANDOM_NUMBER;
    
    -- ==================================================
    -- ランダムな時間を生成する(YYYYMMDD形式)。
    -- ==================================================
    FUNCTION RANDOM_TIME RETURN VARCHAR2
    IS
        V_DATE VARCHAR2(6);
    BEGIN
        V_DATE :=           SUBSTR('00' || RANDOM_NUMBER(0, 23), -2);
        V_DATE := V_DATE || SUBSTR('00' || RANDOM_NUMBER(0, 59), -2);
        V_DATE := V_DATE || SUBSTR('00' || RANDOM_NUMBER(0, 59), -2);
        RETURN V_DATE;
    END RANDOM_TIME;
    
    -- ==================================================
    -- 指定範囲内でランダムな文字列を取得する。
    -- P_RULE
    --   'n'、'N'　：　数値文字列を戻します。
    --   'u'、'U'　：　大文字のアルファベット文字の文字列
    --   'l'、'L'　：　小文字のアルファベット文字の文字列　
    --   'a'、'A'　：　大/小文字が混在したアルファベット文字の文字列
    --   'x'、'X'　：　大文字のアルファベット文字と数字の文字列
    --   'p'、'P'　：　印刷可能な任意の文字の文字列
    -- P_LENGTH 文字長
    -- ==================================================
    FUNCTION RANDOM_VALUE(P_RULE IN CHAR, P_LENGTH IN NUMBER) RETURN VARCHAR2
    IS
    BEGIN
        IF ( UPPER(P_RULE) = 'N') THEN
            V_START := POWER(10,  P_LENGTH     )    ;
            V_END   := POWER(10, (P_LENGTH + 1)) - 1;
            RETURN (TO_CHAR(SUBSTR(DBMS_RANDOM.VALUE(V_START, V_END), 2, P_LENGTH)));
        ELSE
            RETURN DBMS_RANDOM.STRING(P_RULE, P_LENGTH);
        END IF;
    END RANDOM_VALUE;


    -- ----------------------------------------------------------------------------------------------------
    -- ランダムデータ作成（人名/性別/生年月日）を生成
    -- ----------------------------------------------------------------------------------------------------
    FUNCTION GENERATE_HUMANDATA
    RETURN tArraySTR
    IS
        vTMP_INDEX NUMBER(4);
        P_ARRAY tArraySTR;
    BEGIN
        --------------------------------------------------
        -- 苗字
        --------------------------------------------------
        vTMP_INDEX := RANDOM_NUMBER(1, FAMNAME_KANJI.COUNT);
        P_ARRAY('FAMNAME_KANJI') := FAMNAME_KANJI(vTMP_INDEX);
        P_ARRAY('FAMNAME_KANA' ) := FAMNAME_KANA (vTMP_INDEX);
        --------------------------------------------------
        -- 名前/性別/生年月日
        --------------------------------------------------
        vTMP_INDEX                       := RANDOM_NUMBER(1, PERNAME_KANJI.COUNT);
        P_ARRAY('PERNAME_KANJI')         := PERNAME_KANJI(vTMP_INDEX);
        P_ARRAY('PERNAME_KANA' )         := PERNAME_KANA (vTMP_INDEX);
        P_ARRAY('PERNAME_SEX'  )         := PERNAME_SEX  (vTMP_INDEX);
        vTMP_INDEX                       := RANDOM_NUMBER(1, PERNAME_BIRTHDAY.COUNT);
        P_ARRAY('PERNAME_BIRTHDAY')      := PERNAME_BIRTHDAY(vTMP_INDEX);
        vTMP_INDEX                       := RANDOM_NUMBER(1, PERNAME_PORTABLETELNO.COUNT);
        P_ARRAY('PERNAME_PORTABLETELNO') := PERNAME_PORTABLETELNO(vTMP_INDEX);

        RETURN P_ARRAY;
    END GENERATE_HUMANDATA;

    -- ----------------------------------------------------------------------------------------------------
    -- ランダムデータ作成（住所/電話番号）を生成
    -- ----------------------------------------------------------------------------------------------------
    FUNCTION GENERATE_ADDREESSDATA
    RETURN tArraySTR
    IS
        vTMP01_INDEX NUMBER(4);
        vTMP02_INDEX NUMBER(4);
        P_ARRAY tArraySTR;
    BEGIN
        --------------------------------------------------
        -- 住所
        --------------------------------------------------
        vTMP01_INDEX := RANDOM_NUMBER(1, ADDRESS_ZIPCODE.COUNT);
        vTMP02_INDEX := RANDOM_NUMBER(1,  ADDRESS_ADDNUM.COUNT);
        P_ARRAY('ADDRESS_ZIPCODE')   := ADDRESS_ZIPCODE(vTMP01_INDEX);
        P_ARRAY('ADDRESS_ADDRESS')   := ADDRESS_ADDRESS(vTMP02_INDEX) || ADDRESS_ADDNUM(vTMP02_INDEX) || ADDRESS_APERTNAME(vTMP02_INDEX);
        --------------------------------------------------
        -- 電話番号
        --------------------------------------------------
        vTMP01_INDEX                 := RANDOM_NUMBER(1, PERNAME_KANJI.COUNT);
        P_ARRAY('ADDRESS_HOMETELNO') := ADDRESS_HOMETELNO(vTMP01_INDEX);
        P_ARRAY('ADDRESS_FAXTELNO' ) := ADDRESS_FAXTELNO (vTMP01_INDEX);

        RETURN P_ARRAY;
    END GENERATE_ADDREESSDATA;

    -- ----------------------------------------------------------------------------------------------------
    -- CSV出力サンプル
    -- ----------------------------------------------------------------------------------------------------
    FUNCTION SELECT_XXX( V_ARG01 IN VARCHAR2, V_ARG02 IN NUMBER)
    RETURN VARCHAR2
    IS
        RESULT_STR VARCHAR2(4096);
    BEGIN
        BEGIN
            SELECT
                     '"' || NVL(        'A'                           ,'<NULL>') || '"'
                ||  ',"' || NVL(TO_CHAR('B', 'FM9999999999'          ),'<NULL>') || '"'
                ||  ',"' || NVL(TO_CHAR('C', 'YYYY/MM/DD/ HH24;MI:SS'),'<NULL>') || '"'
            INTO RESULT_STR 
            FROM DUAL;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RESULT_STR := '*** RECORD IS NOTHING. ***';
        END;
        
        RETURN RESULT_STR;
    END SELECT_XXX;

