    DBMS_OUTPUT.PUT_LINE(v_HumanData('FAMNAME_KANA' )        );
    DBMS_OUTPUT.PUT_LINE(v_HumanData('PERNAME_KANJI')        );
    DBMS_OUTPUT.PUT_LINE(v_HumanData('PERNAME_KANA' )        );
    DBMS_OUTPUT.PUT_LINE(v_HumanData('PERNAME_SEX'  )        );
    DBMS_OUTPUT.PUT_LINE(v_HumanData('PERNAME_BIRTHDAY')     );
    DBMS_OUTPUT.PUT_LINE(v_HumanData('PERNAME_PORTABLETELNO'));

    -- ----------------------------------------------------------------------------------------------------
    -- 住所をランダムに生成
    -- ----------------------------------------------------------------------------------------------------
    v_AddressData := GENERATE_ADDREESSDATA;
    DBMS_OUTPUT.PUT_LINE(v_AddressData('FAMNAME_KANJI')        );
    DBMS_OUTPUT.PUT_LINE(v_AddressData('FAMNAME_KANA' )        );
    DBMS_OUTPUT.PUT_LINE(v_AddressData('PERNAME_KANJI')        );
    DBMS_OUTPUT.PUT_LINE(v_AddressData('PERNAME_KANA' )        );
    DBMS_OUTPUT.PUT_LINE(v_AddressData('PERNAME_SEX'  )        );
    DBMS_OUTPUT.PUT_LINE(v_AddressData('PERNAME_BIRTHDAY')     );
    DBMS_OUTPUT.PUT_LINE(v_AddressData('PERNAME_PORTABLETELNO'));

    -- ----------------------------------------------------------------------------------------------------
    -- CSV出力系サンプル
    -- ----------------------------------------------------------------------------------------------------
    DBMS_OUTPUT.PUT_LINE('-- ----------------------------------------------------------------------------------------------------');
    DBMS_OUTPUT.PUT_LINE('PRINT CSV @ ' || TO_CHAR(SYSDATE, 'YYYY/MM/DD HH24:MI:SS')                                              );
    DBMS_OUTPUT.PUT_LINE('-- ----------------------------------------------------------------------------------------------------');

    DBMS_OUTPUT.PUT_LINE('-- ==================================================');
    DBMS_OUTPUT.PUT_LINE('-- TABLE:DUAL')
    DBMS_OUTPUT.PUT_LINE('-- ==================================================');
    RECORD_CNT := 0;
    FOR TMP_RECORD IN (SELECT * FROM DUAL) LOOP
        DBMS_OUTPUT.PUT_LINE(SELECT_XXX('AAA', 0));
        RECORD_CNT := RECORD_CNT + 1;
    END LOOP;
    IF RECORD_CNT = 0 THEN
        DBMS_OUTPUT.PUT_LINE('*** RECORD IS NOTHING. ***');
END;
/

EXIT;



